import Foundation
import KeyboardCore
final class Doc: TextDocument {
 var chars:[Character]; var lo:Int;var hi:Int
 let documentIdentifier:UUID? = UUID()
 init(_ before:String,_ after:String){chars=Array(before+after);lo=before.count;hi=lo}
 var text:String {String(chars)}
 var documentContextBeforeInput:String? {String(chars.prefix(lo))}
 var documentContextAfterInput:String? {String(chars.dropFirst(hi))}
 var selectedText:String? {lo==hi ? nil:String(chars[lo..<hi])}
 var hasText:Bool {!chars.isEmpty}
 func insertText(_ value:String){chars.replaceSubrange(lo..<hi,with:Array(value));lo+=value.count;hi=lo}
 func deleteBackward(){if lo != hi {chars.removeSubrange(lo..<hi);hi=lo} else if lo>0 {chars.remove(at:lo-1);lo-=1;hi=lo}}
}
let base="/tmp/pulpo-r19-author-baseline/apps/keyboard-ios/LanguageData/"
let obj=try JSONSerialization.jsonObject(with:Data(contentsOf:URL(fileURLWithPath:CommandLine.arguments[1]))) as! [String:Any]
var results:[[String:Any]]=[]
for mode in ["en","es","bi"] {
 for r in obj["cases"] as! [[String:Any]] {
  let stack=try LanguageStack(dictionaryURL:URL(fileURLWithPath:base+["en":"en_US.pkdict","es":"es.pkdict","bi":"en_es.pkdict"][mode]!),personalURL:nil)
  let doc=Doc(r["before"] as! String,r["after"] as! String)
  var settings=KeyboardSettings();settings.language=["en":KeyboardLanguage.english,"es":.spanish,"bi":.bilingual][mode]!
  var traits=InputTraits();traits.capitalization = .none
  func makeEngine()->KeyboardEngine {let e=KeyboardEngine(document:doc,suggester:stack.suggester,glide:stack.glide,settings:settings);e.traits=traits;return e}
  var engine=makeEngine();var checkpoints:[[String:Any]]=[]
  for (index,op) in (r["operations"] as! [[String:Any]]).enumerated() {
   switch op["op"] as! String {
   case "insert":for ch in op["text"] as! String {if ch==" " {engine.insertSpace()} else if ch=="\n" {engine.insertReturn()} else {engine.insertCharacter(String(ch))}}
   case "backspace":for _ in 0..<(op["count"] as? Int ?? 1){engine.deleteBackward()}
   case "move":doc.lo += op["offset"] as! Int;doc.hi=doc.lo;engine.reconcileHostChanges()
   case "select":doc.lo=op["start"] as! Int;doc.hi=op["end"] as! Int;engine.reconcileHostChanges()
   case "sync":engine.reconcileHostChanges()
   case "private":traits.isSecure=op["enabled"] as! Bool;engine.traits=traits
   case "reset":engine=makeEngine()
   case "undo":if engine.deleteUndoesLastEdit {engine.deleteBackward()}
   default:fatalError("Unknown operation")
   }
   var cp:[String:Any]=["index":index,"document":doc.text]
   if let state=op["expectState"] as? [String:Any] {
    var counts:[String:Int]=[:];for word in (state["personalCounts"] as! [String:Int]).keys{counts[word]=stack.personal.count(of:word)}
    cp["state"]=["personalTotalCount":stack.personal.totalCount,"personalCounts":counts]
   }
   checkpoints.append(cp)
  }
  results.append(["id":r["id"]!,"mode":mode,"document":doc.text,"checkpoints":checkpoints])
 }
}
print(String(data:try JSONSerialization.data(withJSONObject:results,options:[.prettyPrinted,.sortedKeys]),encoding:.utf8)!)
